import json

class custom_dataset_Processor(DatasetProcessor):
    def __init__(self, cv=0):
        # Load only the first 10 entries from each split
        self.train_examples = self._read_jsonl('/workspace/custom_dataset/train.jsonl', 'train')
        self.dev_examples = self._read_jsonl('/workspace/custom_dataset/val.jsonl', 'dev')
        self.test_examples = self._read_jsonl('/workspace/custom_dataset/test.jsonl', 'test')

    def _read_jsonl(self, file_path, set_type):
        examples = []
        with open(file_path, 'r') as f:
            for i, line in enumerate(f):
                if i >= 10:
                    break
                entry = json.loads(line)
                # Assuming standard OBQA: question + (possible) answer choices and gold
                guid = f"{set_type}-{i}"
                question = entry.get('question', '')
                context = entry.get('context', '')
                label = entry.get('label', entry.get('answerKey', None))
                choices = entry.get('choices', [])

                # For consistency with InputExample: main text as text_a, option for text_b
                if choices:
                    for c in choices:
                        ex = InputExample(
                            guid=guid,
                            text_a=' '.join([context, question, c['text']]).strip(),
                            label=label if c['label'] == label else None
                        )
                        examples.append(ex)
                else:
                    examples.append(InputExample(guid=guid, text_a=question, label=label))

        # Only keep the *first 10* InputExamples (ensures no more than 10 per split)
        return examples[:10]

    def get_train_examples(self, cv=0):
        return self.train_examples
    def get_test_examples(self, cv=0):
        return self.test_examples
    def get_dev_examples(self, cv=0):
        return self.dev_examples
    def get_labels(self):
        labels = set()
        for ex in self.train_examples + self.dev_examples + self.test_examples:
            if ex.label is not None:
                labels.add(ex.label)
        return sorted(labels)

